**Matcher.** Two pointers with star backtracking:

```javascript
let p = 0, w = 0, star = -1, resume = 0;
while (w < word.length) {
  if (p < symbols.length && (symbols[p] === '?' || symbols[p] === word[w])) { p++; w++; }
  else if (p < symbols.length && symbols[p] === '*') { star = p; resume = w; p++; }
  else if (star >= 0) { resume++; p = star + 1; w = resume; } // star absorbs one more letter
  else return false;
}
while (p < symbols.length && symbols[p] === '*') p++;
return p === symbols.length;
```

